"""Emit kernel-checkable certificates into QEC360_STAGE."""
import os
from pathlib import Path
STAGE=Path(os.environ["QEC360_STAGE"]).resolve()
import json, sys
sys.path.insert(0, str(STAGE))
from balanced_nat_literal import literal
x = json.load(open(str(STAGE / 'census_translation_closure.json')))
cs = sum(x['coefficientsByBasisThenTranslation'], [])
packed = sum((c << 43 * i for i, c in enumerate(cs)))
s = 'import GBReflectedAction\nimport MaskLinear\nimport Bravyi360ReachabilityData\nset_option maxRecDepth 100000\nset_option maxHeartbeats 0\nnamespace Quantum.Stabilizer.Homological.BB.Bravyi360\nopen F2Mask\n\n/-- Coordinates reconstructing all45 translations of each reachable generator. -/\ndef reachableTranslationCoefficients : Nat := ' + literal(packed, 4096) + '\n\n/-- Read the43-bit coefficient vector for a generator translation. -/\ndef reachableTranslationCoefficient (g i : Nat) : Nat :=\n  PackedDigits.lane 43 (45*g+i) reachableTranslationCoefficients\n\n/-- The reachable generator at its stored coordinate index. -/\ndef reachableGeneratorAt (g : Nat) : Nat := (ReachabilityData.reachableGenerators[g]!).2\n\n/-- All45 translated forms of every reachable generator reconstruct within the reachable frame. -/\ntheorem reachable_translation_checked : ∀ g : Fin 43, ∀ i : Fin 45,\n    GBOrbit.entry (reachableGeneratorAt g.val % 2^45) (reachableGeneratorAt g.val / 2^45) i.val =\n      reconX ReachabilityData.reachableGenerators (reachableTranslationCoefficient g.val i.val) := by\n  decide +kernel\n\n/-- Each stored frame column carries its valid generator index. -/\ntheorem reachable_generator_index : ∀ p ∈ ReachabilityData.reachableGenerators,\n    p.1 < 43 ∧ p.2 = reachableGeneratorAt p.1 := by decide +kernel\n\n/-- Translate a packed chain in the concrete reflected laboratory coordinate convention. -/\ndef translateMask (g : BaseGroup) (word : Nat) : Nat :=\n  maskOf baseQubitEnum (translate1 g (chainOfMask baseQubitEnum word))\n\n/-- Translation sends the zero mask to zero. -/\ntheorem translateMask_zero (g : BaseGroup) : translateMask g 0 = 0 := by\n  have hz : translate1 g (0 : BaseGroup × Fin 2 → ZMod 2) = 0 := rfl\n  rw [translateMask, chainOfMask_zero, hz, maskOf_zero]\n\n/-- Translating binary masks commutes with exclusive-or. -/\ntheorem translateMask_xor (g : BaseGroup) (a b : Nat) :\n    translateMask g (a ^^^ b) = translateMask g a ^^^ translateMask g b := by\n  unfold translateMask\n  rw [chainOfMask_xor]\n  have hadd : translate1 g (chainOfMask baseQubitEnum a + chainOfMask baseQubitEnum b) =\n      translate1 g (chainOfMask baseQubitEnum a) + translate1 g (chainOfMask baseQubitEnum b) := rfl\n  rw [hadd, maskOf_add]\n\n/-- Every translated frame generator remains in the reachable span. -/\ntheorem translateMask_generator_mem (g : BaseGroup) (p : Nat × Nat)\n    (hp : p ∈ ReachabilityData.reachableGenerators) :\n    XorSpan (ReachabilityData.reachableGenerators.map Prod.snd) (translateMask g p.2) := by\n  have hi := reachable_generator_index p hp\n  have hfit := ReachabilityData.reachableGenerators_bounded p hp\n  let idx := 15*g.2.val+(-g.1).val\n  have hidx : idx < 45 := by\n    have := ZMod.val_lt g.2\n    have := ZMod.val_lt (-g.1)\n    dsimp [idx]\n    omega\n  have ht := entry_reflected_mask (chainOfMask baseQubitEnum p.2) (-g.1) g.2\n  rw [maskOf_chainOfMask baseQubitEnum hfit] at ht\n  simp only [neg_neg, Prod.mk.eta] at ht\n  unfold translateMask\n  rw [← ht, hi.2, reachable_translation_checked ⟨p.1,hi.1⟩ ⟨idx,hidx⟩]\n  exact reconX_mem_span _ _\n\n/-- The43-dimensional reachable span is invariant under every physical base translation. -/\ntheorem reachable_span_translate {word : Nat}\n    (h : XorSpan (ReachabilityData.reachableGenerators.map Prod.snd) word) (g : BaseGroup) :\n    XorSpan (ReachabilityData.reachableGenerators.map Prod.snd) (translateMask g word) := by\n  induction h with\n  | zero => rw [translateMask_zero]; exact .zero\n  | @step a word ha _ ih =>\n    obtain ⟨p,hp,rfl⟩ := List.mem_map.mp ha\n    rw [translateMask_xor]\n    exact (translateMask_generator_mem g p hp).xor ih\n\n/-- Translating a base chain preserves membership of its mask in the reachable span. -/\ntheorem reachable_chain_translate (v : BaseGroup × Fin 2 → ZMod 2)\n    (h : XorSpan (ReachabilityData.reachableGenerators.map Prod.snd) (maskOf baseQubitEnum v))\n    (g : BaseGroup) :\n    XorSpan (ReachabilityData.reachableGenerators.map Prod.snd)\n      (maskOf baseQubitEnum (translate1 g v)) := by\n  simpa only [translateMask, chainOfMask_maskOf] using reachable_span_translate h g\n\nend Quantum.Stabilizer.Homological.BB.Bravyi360\n'
open(str(STAGE / 'ReachableTranslation.lean'), 'w').write(s)
